  final tracks = pathsCsv.split(',').map((path) {
    final trimmed = path.trim();
    return AudioTrack(path: trimmed, title: trimmed.split('/').last);
  }).toList();

  await p.setQueue(tracks, startIndex: startIndex, shuffle: shuffle);
  return _ok({'queued': tracks.length, 'startIndex': startIndex, 'shuffle': shuffle});
}

